def solve_n(n):
    solutions = []
    def backtrack(k, current_sum_a, current_sum_ka, current_a):
        if k == n + 1:
            if current_sum_a == n + 1 and current_sum_ka == n + 1:
                b = [0] * (n + 1)
                for x in current_a:
                    if 0 <= x <= n:
                        b[x] += 1
                a_calc = [0] * (n + 1)
                for x in b:
                    if 0 <= x <= n:
                        a_calc[x] += 1
                if current_a == a_calc:
                    solutions.append(list(current_a))
            return

        max_ak = n + 1
        if k > 0:
            max_ak = (n + 1 - current_sum_ka) // k
        max_ak = min(max_ak, n + 1 - current_sum_a)

        # One more pruning: sum_{i=k+1}^n i*a_i = n+1 - current_sum_ka
        # and sum_{i=k+1}^n a_i = n+1 - current_sum_a
        # The maximum sum_{i=k+1}^n i*a_i is n * (n+1 - current_sum_a).
        # So we need n+1 - current_sum_ka <= n * (n+1 - current_sum_a - val).

        for val in range(max_ak + 1):
            current_a.append(val)
            rem_sum_a = (n + 1) - (current_sum_a + val)
            rem_sum_ka = (n + 1) - (current_sum_ka + k * val)
            if rem_sum_ka <= n * rem_sum_a:
                backtrack(k + 1, current_sum_a + val, current_sum_ka + k * val, current_a)
            current_a.pop()

    backtrack(0, 0, 0, [])
    return solutions

for n in range(1, 11):
    sols = solve_n(n)
    print(f"n={n}, solutions={sols}")

